-- Prefactura "mínima": hoy generar_prefacturas_periodo exige que la ODT
-- tenga vehiculo_id resuelto Y que ese vehículo tenga transportista_id
-- asignado; si falta cualquiera de los dos, la ODT queda totalmente fuera
-- (ni siquiera se crea la prefactura). Esto bloqueaba el flujo cuando se
-- carga el corte de ODT antes de terminar de cargar Vehículos/Transportistas:
-- se pidió poder generar igual la prefactura con el mínimo de datos
-- disponible (placa + un nombre, de transportista o del campo Chofer de la
-- ODT) para poder trabajar con ella (PDF con los demás campos en blanco,
-- aparece en Control por placa, etc.), y que se complete sola -sin duplicar-
-- la próxima vez que se le dé a "Generar prefacturas" una vez que el
-- vehículo/transportista ya estén cargados.
-- Cada sentencia de abajo está en UNA sola línea a propósito (ver migraciones
-- anteriores): el editor/proceso que corre esto ejecuta línea por línea.
alter table public.prefactura alter column vehiculo_id drop not null;
alter table public.prefactura alter column transportista_id drop not null;
alter table public.prefactura add column if not exists placa_normalizada text;
alter table public.prefactura add column if not exists nombre_pendiente text;
update public.prefactura p set placa_normalizada = v.placa from public.vehiculo v where p.vehiculo_id = v.id and p.placa_normalizada is null;
alter table public.prefactura alter column placa_normalizada set not null;
drop index if exists public.prefactura_vehiculo_periodo_principal_key;
create unique index if not exists prefactura_placa_periodo_principal_key on public.prefactura (placa_normalizada, periodo_id) where es_principal;
comment on column public.prefactura.placa_normalizada is 'Placa (normalizada) de las ODT agrupadas en esta prefactura. Se guarda siempre, incluso antes de que exista un vehículo registrado con esa placa ("prefactura mínima") — es la llave real de agrupación de las principales, vía el índice único (placa_normalizada, periodo_id) where es_principal, reemplazando a la antigua (vehiculo_id, periodo_id). Cuando el vehículo se registra, generar_prefacturas_periodo encuentra esta misma fila por placa y la completa con vehiculo_id/transportista_id en vez de crear una prefactura nueva.';
comment on column public.prefactura.nombre_pendiente is 'Nombre de respaldo (tomado del campo Chofer de las ODT del período, el más reciente no vacío) para una prefactura sin transportista_id resuelto todavía — se usa como nombre en el PDF y en pantalla mientras tanto. Vuelve a null solo cuando transportista_id deja de ser null.';
drop function if exists public.generar_prefacturas_periodo(uuid);
create or replace function public.generar_prefacturas_periodo(p_periodo_id uuid) returns table (prefacturas_creadas integer, prefacturas_actualizadas integer, prefacturas_requieren_regenerar integer) language plpgsql security invoker set search_path = public as $$ declare v_creadas integer := 0; v_actualizadas integer := 0; v_requieren_regenerar integer := 0; begin update odt o set vehiculo_id = v.id from vehiculo v where o.periodo_id = p_periodo_id and o.vehiculo_id is null and o.placa_normalizada = v.placa and v.deleted_at is null; with previos as (select p.id, p.placa_normalizada, p.transportista_id, p.estado, exists (select 1 from documento_pdf dp where dp.prefactura_id = p.id and dp.estado = 'VIGENTE') as tiene_pdf_vigente from prefactura p where p.periodo_id = p_periodo_id and p.es_principal), descuentos_odt as (select odt_id, sum(valor) as valor from descuento where deleted_at is null group by odt_id), agregado as (select o.placa_normalizada, (array_agg(v.id) filter (where v.id is not null))[1] as vehiculo_id, (array_agg(v.transportista_id) filter (where v.transportista_id is not null))[1] as transportista_id, count(*) as cantidad_odt, sum(coalesce(o.valor_final, o.valor)) as total_odt, coalesce(sum(d.valor), 0) as total_descuentos, (array_agg(o.chofer order by o.fecha_creacion desc nulls last) filter (where o.chofer is not null and btrim(o.chofer) <> ''))[1] as nombre_pendiente from odt o left join vehiculo v on v.id = o.vehiculo_id left join descuentos_odt d on d.odt_id = o.id where o.periodo_id = p_periodo_id and o.placa_normalizada is not null group by o.placa_normalizada), upsert as (insert into prefactura (periodo_id, vehiculo_id, transportista_id, placa_normalizada, nombre_pendiente, total_odt, total_descuentos, total, cantidad_odt, estado) select p_periodo_id, a.vehiculo_id, a.transportista_id, a.placa_normalizada, case when a.transportista_id is null then a.nombre_pendiente else null end, a.total_odt, a.total_descuentos, a.total_odt - a.total_descuentos, a.cantidad_odt, 'BORRADOR' from agregado a on conflict (placa_normalizada, periodo_id) where es_principal do update set vehiculo_id = excluded.vehiculo_id, transportista_id = excluded.transportista_id, nombre_pendiente = excluded.nombre_pendiente, total_odt = excluded.total_odt, total_descuentos = excluded.total_descuentos, total = excluded.total_odt - excluded.total_descuentos, cantidad_odt = excluded.cantidad_odt, estado = case when prefactura.estado in ('BORRADOR', 'CON_NOVEDADES') then 'BORRADOR' when prefactura.estado <> 'ANULADA' and prefactura.transportista_id is distinct from excluded.transportista_id and exists (select 1 from documento_pdf dp where dp.prefactura_id = prefactura.id and dp.estado = 'VIGENTE') then 'REQUIERE_REGENERAR' else prefactura.estado end returning id, (xmax = 0) as es_nuevo, placa_normalizada, transportista_id) select count(*) filter (where u.es_nuevo)::integer, count(*) filter (where not u.es_nuevo)::integer, count(*) filter (where not u.es_nuevo and pr.estado <> 'ANULADA' and pr.tiene_pdf_vigente and pr.transportista_id is distinct from u.transportista_id)::integer into v_creadas, v_actualizadas, v_requieren_regenerar from upsert u left join previos pr on pr.placa_normalizada = u.placa_normalizada; insert into prefactura_detalle (prefactura_id, odt_id) select p.id, o.id from odt o join prefactura p on p.placa_normalizada = o.placa_normalizada and p.periodo_id = p_periodo_id and p.es_principal where o.periodo_id = p_periodo_id and o.placa_normalizada is not null on conflict (prefactura_id, odt_id) do nothing; return query select v_creadas, v_actualizadas, v_requieren_regenerar; end; $$;
comment on function public.generar_prefacturas_periodo(uuid) is 'Botón "Generar prefacturas del período": vincula ODT huérfanas, hace UPSERT de 1 prefactura PRINCIPAL por placa (no por vehículo: así existe aunque la placa no tenga vehículo/transportista registrado todavía — queda "mínima", con nombre_pendiente tomado del Chofer), congela prefactura_detalle. El correlativo solo se asigna a las nuevas. Si el vehículo/transportista cambia y la prefactura ya tenía PDF vigente (y no está ANULADA), la marca REQUIERE_REGENERAR en vez de actualizarla en silencio.';
